an__sm=\"12\"]\n\n[ux_image_box img=\"188\"]\n\n<p><strong>High quality imported materials</strong></p>\n\n[/ux_image_box]\n\n[/col_inner]\n\n[/row_inner]\n\n[/ux_slider]\n\n[/col]\n\n[/row]\n\n[/section]\n[section bg_color=\"rgb(102, 101, 101)\"]\n\n[row]\n\n[col span__sm=\"12\" padding=\"0px 0px 0px 0px\" align=\"center\"]\n\n<p class=\"h-brand-badge text-center text-uppercase\"><span style=\"color: #ffffff;\"><strong>PRODUCT</strong></span></p>\n<h2 class=\"t-title text-center text-uppercase\"><span style=\"font-size: 115%; color: #ffffff;\">HOUSING SOLUTIONS</span></h2>\n<div class=\"d-br-none text-center mr-25-35 mb-5\">\n<p><span style=\"color: #ffffff;\">Comprehensive solutions for housing,</span><br /><span style=\"color: #ffffff;\">brings comfort to users</span></p>\n</div>\n\n[/col]\n\n[/row]\n\n[/section]\n[section padding=\"0px\"]\n\n[row padding=\"0px 0px 0px 0px\"]\n\n[col span__sm=\"12\" padding=\"20px 0px 0px 0px\" margin=\"20px 0px 0px 0px\"]\n\n[rem_category_grid children_rem_cua=\"33,30,36,31,32,29\"]\n\n[rem_category_grid parent=\"rem-chuyen-dung\"]\n\n\n[/col]\n\n[/row]\n\n[/section]\n[section padding=\"0px\"]\n\n[row]\n\n[col span__sm=\"12\" align=\"center\"]\n\n<p class=\"h-brand-badge text-center text-uppercase\"><strong>PROJECT</strong></p>\n<h2 class=\"t-title text-center text-uppercase\"><span style=\"font-size: 115%;\">TYPICAL WORKS</span></h2>\n\n[/col]\n\n[/row]\n[tabgroup align=\"center\"]\n\n[tab title=\"Apartments, high-rise offices\"]\n\n[ux_slider style=\"container\" slide_width=\"35%\" class=\"sec_cong_trinh_tieu_bieu\"]\n\n[row style=\"collapse\"]\n\n[col span__sm=\"12\"]\n\n[ux_image id=\"63\" margin=\"0px 0px 0px 0px\"]\n\n[ux_html]\n\n<div class=\"home-project-slider-info\">\n                                <p class=\"home-project-slider-name\">FPT University</p>\n                                <a href=\"#\" class=\"btn btn-1\">See details</a>\n                            </div>\n[/ux_html]\n\n[/col]\n[col span__sm=\"12\"]\n\